script:
registro_name = frappe.form_dict.registro_name
registro = frappe.get_doc("Registro de Atos", registro_name)

total = 0
descricao_partes = []

for ato in registro.atos:
    if ato.status == "Pendente" and (ato.valor or 0) > 0:
        total = total + ato.valor
        descricao_partes.append((ato.tipo or "") + ": " + (ato.descrição or "") + " (R$ " + str(ato.valor) + ")")

if total <= 0:
    frappe.throw("Não há atos pendentes para cobrar.")

descricao_final = "\n".join(descricao_partes)

fatura = frappe.get_doc({
    "doctype": "Sales Invoice",
    "customer": registro.cliente,
    "company": "Carine Pagel Advocacia",
    "posting_date": frappe.utils.today(),
    "due_date": frappe.utils.today(),
    "custom_servico": registro.servico,
    "remarks": "ATOS:" + registro_name,
    "items": [{
        "item_code": "HONOR-001",
        "qty": 1,
        "rate": total,
        "description": descricao_final or "Atos Advocatícios"
    }]
})
fatura.insert(ignore_permissions=True)

for ato in registro.atos:
    if ato.status == "Pendente" and (ato.valor or 0) > 0:
        ato.status = "Cobrado"

registro.save(ignore_permissions=True)
frappe.db.commit()

frappe.response["message"] = {"total": total, "fatura": fatura.name}
